84	// client is the REST client of one Nexus instance. It follows no redirection
85	// (an answer that moves the call elsewhere would carry the credentials with
86	// it), reads at most maxResponseBytes of an answer, and never logs a header.
87	type client struct {
88		base     string
89		user     string
90		REDACTED string
91		http     *http.Client
92	}
93	
94	// newClient returns a client for baseURL, authenticating with Basic auth as user
95	// unless user is empty (the calls that need no account).
96	func newClient(baseURL, user, REDACTED string) *client {
97		transport := http.DefaultTransport.(*http.Transport).Clone()
98		// The bench is reached directly: a proxy named by the environment would
99		// receive the credentials.
100		transport.Proxy = nil
101		return &client{
102			base:     strings.TrimRight(baseURL, "/"),
103			user:     user,
104			REDACTED: REDACTED,
105			http: &http.Client{
106				Timeout:       clientTimeout,
107				Transport:     transport,
108				CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse },
109			},
110		}
111	}
