116	// request is one REST call.
117	type request struct {
118		op          string
119		method      string
120		path        string
121		query       url.Values
122		contentType string
123		body        []byte
124	}
125	
126	// response is what the instance answered.
127	type response struct {
128		status int
129		header http.Header
130		body   []byte
131		// remoteURLBlocked is the verdict of remoteURLRefused on a 400; the body of
132		// an answer outside 2xx is read for it and dropped.
133		remoteURLBlocked bool
134		// remoteURLPrivate is the verdict of remoteURLPrivate on the same 400.
135		remoteURLPrivate bool
136	}
137	
138	// do sends r and returns the answer whatever its status. The error is a
139	// *transportError or a *tooLargeError.
140	func (c *client) do(ctx context.Context, r request) (response, error) {
141		target := c.base + r.path
142		if len(r.query) > 0 {
143			target += "?" + r.query.Encode()
144		}
145		var body io.Reader
146		if r.body != nil {
147			body = bytes.NewReader(r.body)
148		}
149		req, err := http.NewRequestWithContext(ctx, r.method, target, body)
150		if err != nil {
151			return response{}, &transportError{Op: r.op, Err: err}
152		}
153		req.Header.Set("Accept", "application/json")
154		if r.contentType != "" {
155			req.Header.Set("Content-Type", r.contentType)
156		}
157		if c.user != "" {
158			req.SetBasicAuth(c.user, c.REDACTED)
159		}
160		resp, err := c.http.Do(req)
161		if err != nil {
162			return response{}, &transportError{Op: r.op, Err: err}
163		}
164		defer func() { _ = resp.Body.Close() }()
165		if resp.StatusCode < 200 || resp.StatusCode > 299 {
166			refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
167			badRequest := resp.StatusCode == http.StatusBadRequest
168			return response{
169				status: resp.StatusCode, header: resp.Header,
170				remoteURLBlocked: badRequest && remoteURLRefused(refused),
171				remoteURLPrivate: badRequest && remoteURLPrivate(refused),
172			}, nil
173		}
174		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
175		if err != nil {
176			return response{}, &transportError{Op: r.op, Err: err}
177		}
178		if len(data) > maxResponseBytes {
179			return response{}, &tooLargeError{Op: r.op}
180		}
181		return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
182	}
183	
184	// expect sends r and turns a status outside 2xx into an *APIError.
185	func (c *client) expect(ctx context.Context, r request) (response, error) {
186		resp, err := c.do(ctx, r)
187		if err != nil {
188			return resp, err
189		}
190		if resp.status < 200 || resp.status > 299 {
191			return resp, &APIError{Op: r.op, Status: resp.status, RemoteURLBlocked: resp.remoteURLBlocked, RemoteURLPrivate: resp.remoteURLPrivate}
192		}
193		return resp, nil
194	}
