196	// remoteURLRefused reports whether body is a Nexus validation error list with
197	// an entry on proxy.remoteUrl whose message says the host did not resolve:
198	// [{"id":"HelperBean.proxy.remoteUrl","message":"... Failed to resolve host: ..."}].
199	// Only that verdict leaves the function: no text of the answer is kept. The
200	// content type of the answer is vendor specific, so only the JSON is read; a
201	// body past drainBytes was cut and is not trusted.
202	func remoteURLRefused(body []byte) bool {
203		return remoteURLMessageHas(body, "resolve host")
204	}
205	
206	// remoteURLPrivate reports whether body is a validation error list with an entry
207	// on proxy.remoteUrl that says the host resolves to a private address, which is
208	// what the SSRF protection of Nexus 3.98 answers (observed on 3.98.1-01:
209	// "Proxy URL blocked: Host resolves to private/local IP address(es): ..."). Same
210	// rules as remoteURLRefused: only the verdict leaves the function.
211	func remoteURLPrivate(body []byte) bool {
212		return remoteURLMessageHas(body, "resolves to private")
213	}
214	
215	// remoteURLMessageHas reports whether body is a validation error list with an
216	// entry on proxy.remoteUrl whose message contains fragment, case-insensitive.
217	func remoteURLMessageHas(body []byte, fragment string) bool {
218		if len(body) > drainBytes {
219			return false
220		}
221		var errs []validationError
222		if err := json.Unmarshal(body, &errs); err != nil {
223			return false
224		}
225		return slices.ContainsFunc(errs, func(e validationError) bool {
226			return strings.HasSuffix(e.ID, "proxy.remoteUrl") &&
227				strings.Contains(strings.ToLower(e.Message), fragment)
228		})
229	}
