238	// get reads path and decodes the JSON answer into out (nil: not decoded). A 404
239	// is found == false without an error.
240	func (c *client) get(ctx context.Context, op, path string, query url.Values, out any) (found bool, err error) {
241		resp, err := c.do(ctx, request{op: op, method: http.MethodGet, path: path, query: query})
242		if err != nil {
243			return false, err
244		}
245		switch {
246		case resp.status == http.StatusNotFound:
247			return false, nil
248		case resp.status < 200 || resp.status > 299:
249			return false, &APIError{Op: op, Status: resp.status}
250		}
251		if out == nil {
252			return true, nil
253		}
254		if err := json.Unmarshal(resp.body, out); err != nil {
255			return false, &decodeError{Op: op, Err: err}
256		}
257		return true, nil
258	}
259	
260	// read is get for an object that has to exist: a 404 is an *APIError.
261	func (c *client) read(ctx context.Context, op, path string, query url.Values, out any) error {
262		found, err := c.get(ctx, op, path, query, out)
263		if err != nil {
264			return err
265		}
266		if !found {
267			return &APIError{Op: op, Status: http.StatusNotFound}
268		}
269		return nil
270	}
271	
272	// write sends payload as JSON with method and expects a 2xx.
273	func (c *client) write(ctx context.Context, op, method, path string, payload any) error {
274		data, err := json.Marshal(payload)
275		if err != nil {
276			return &decodeError{Op: op, Err: err}
277		}
278		_, err = c.expect(ctx, request{op: op, method: method, path: path, contentType: "application/json", body: data})
279		return err
280	}
